const { readdirSync, writeFileSync } = require("fs");
const path = require("path");

const ROOT = "api/v1/routes";
const OUT = path.join(ROOT, "routes.ts");

const files = readdirSync(ROOT, { recursive: true, encoding: "utf8" })
    .map((f) => f.split(path.sep).join("/")) // normalize on Windows
    .filter(
        (f) =>
            f !== "routes.ts" &&
            f.endsWith(".ts") &&
            !f.endsWith(".d.ts") &&
            !f.endsWith(".test.ts"),
    )
    .map((f) => f.replace(/\.ts$/, ""))
    .sort();

const lines = [
    "// AUTO-GENERATED by scripts/gen-routes.js. Do not edit.",
    'import type { Express } from "express";',
    'import type { Utils } from "../../../index.ts";',
    ...files.map((f, i) => `import r${i} from "./${f}"; // ${f}`),
    "",
    "export const routes: Array<(app: Express, utils: Utils) => void> = [",
    ...files.map((_, i) => `  r${i},`),
    "];",
    "",
    "export function registerRoutes(app: Express, utils: Utils): void {",
    "    for (const register of routes) {",
    "        register(app, utils);",
    "    }",
    "}",
    "",
];

writeFileSync(OUT, lines.join("\n"));
console.log(`Generated ${OUT} with ${files.length} routes`);
